    /** Stages 193-194: null when the torches in the box (rel lo..hi) are exactly the wanted slots (rel cell -> its wall), each a wall torch on that wall; else what's off. */
    private static String stTorchesWrong(GameTestHelper h, java.util.Map<BlockPos, net.minecraft.core.Direction> want, BlockPos lo, BlockPos hi) {
        StringBuilder bad = new StringBuilder(); java.util.Set<BlockPos> got = new java.util.HashSet<>();
        for (BlockPos q : BlockPos.betweenClosed(lo, hi)) {
            var s = h.getBlockState(q); if (!s.is(Blocks.WALL_TORCH) && !s.is(Blocks.TORCH)) continue;
            BlockPos r = q.immutable(); got.add(r); var wd = want.get(r);
            if (wd == null) bad.append(" off-slot torch at ").append(r.toShortString());
            else if (!s.is(Blocks.WALL_TORCH) || s.getValue(net.minecraft.world.level.block.WallTorchBlock.FACING) != wd.getOpposite()) bad.append(" the torch at ").append(r.toShortString()).append(" isn't on the ").append(wd.getName()).append(" wall");
        }
        for (BlockPos w : want.keySet()) if (!got.contains(w)) bad.append(" no torch in slot ").append(w.toShortString());
        return bad.length() == 0 ? null : bad.toString().trim();
    }
