    /** True when nothing worth taking is left in the chest at {@code abs} (what a looted chest looks like). */
    private static boolean noValuables(ServerLevel level, BlockPos abs) {
        if (!(level.getBlockEntity(abs) instanceof net.minecraft.world.Container box)) return false;
        for (int i = 0; i < box.getContainerSize(); i++) if (com.claudemod.director.ClaudeLife.lootValue(box.getItem(i)) > 0) return false;
        return true;
    }

    /** Step k of the test staircase (heading east from x=1, feet at y=8, down one per step), column z (6 or 7). */
    private static BlockPos stairFeet(int k, int z) { return new BlockPos(1 + k, 8 - k, z); }

    /** A 2-wide, 4-tall staircase down 10 steps through solid stone; jog=1 shifts steps 8+ one block to the side. */
    private static void buildStairs(GameTestHelper h, int jog) {
        for (int x = 0; x < 16; x++) for (int z = 0; z < 16; z++) for (int yy = -4; yy <= 13; yy++) h.setBlock(new BlockPos(x, yy, z), Blocks.STONE);
        for (int k = 0; k <= 10; k++) for (int z = 6; z <= 7; z++) for (int hh = 0; hh < 4; hh++) h.setBlock(stairFeet(k, z + (k >= 8 ? jog : 0)).above(hh), Blocks.AIR);
    }

    /** What's wrong with the test staircase (null if every step is open, floored and roofed, with its walls in). */
    private static String stairsWrong(GameTestHelper h, int jog) {
        for (int k = 1; k <= 10; k++) for (int z = 6; z <= 7; z++) {
            BlockPos f = stairFeet(k, z + (k >= 8 ? jog : 0));
            for (int hh = 0; hh < 4; hh++) if (!h.getBlockState(f.above(hh)).isAir() && !h.getBlockState(f.above(hh)).is(Blocks.WALL_TORCH)) return "step " + k + " walkway blocked at " + f.above(hh).toShortString() + " by " + h.getBlockState(f.above(hh)).getBlock();
            if (h.getBlockState(f.below()).isAir()) return "step " + k + " no floor at " + f.below().toShortString();
            if (h.getBlockState(f.above(4)).isAir()) return "step " + k + " no roof at " + f.above(4).toShortString();
        }
        for (int k = 1; k <= 10; k++) for (int hh = 0; hh < 4; hh++) {
            if (h.getBlockState(stairFeet(k, 5).above(hh)).isAir()) return "step " + k + " left wall open at " + stairFeet(k, 5).above(hh).toShortString();
            if (h.getBlockState(stairFeet(k, 8).above(hh)).isAir()) return "step " + k + " right wall open";
        }
        return null;
    }

