    /** Stages 160-162: his pile, dropped where he stands (his, like a death), then him back at 'from'; the clock set to 'age'. */
    private static java.util.List<net.minecraft.world.entity.item.ItemEntity> clockPile(ClaudeEntity c, ServerLevel level, BlockPos at, BlockPos from, int age) {
        c.teleportTo(at.getX() + 0.5, at.getY(), at.getZ() + 0.5);
        var out = new java.util.ArrayList<net.minecraft.world.entity.item.ItemEntity>();
        for (ItemStack s : java.util.List.of(new ItemStack(Items.IRON_SWORD), new ItemStack(Items.IRON_INGOT, 7), new ItemStack(Items.COBBLESTONE, 20))) {
            var it = new net.minecraft.world.entity.item.ItemEntity(level, at.getX() + 0.5, at.getY() + 0.1, at.getZ() + 0.5, s, 0, 0, 0);
            it.setNeverPickUp(); // (the walk is what's watched, not the pickup)
            level.addFreshEntity(it); out.add(it);
        }
        com.claudemod.director.ClaudeLife.markOwnDrops(c);
        c.teleportTo(from.getX() + 0.5, from.getY(), from.getZ() + 0.5);
        c.setLastDeathLocation(java.util.Optional.of(net.minecraft.core.GlobalPos.of(level.dimension(), at)));
        for (var it : out) clockAge(it, age);
        return out;
    }
