    private static com.claudemod.entity.life.MineBlueprint nightMine(GameTestHelper h, ServerLevel level) {
        flatBox(h);
        for (int x = 0; x < 16; x++) for (int z = 0; z < 16; z++) h.setBlock(new BlockPos(x, -4, z), Blocks.STONE);
        var b = new com.claudemod.entity.life.MineBlueprint(h.absolutePos(new BlockPos(3, 2, 8)), net.minecraft.core.Direction.EAST, 2, 4);
        b.segments.get(0).n = 6; b.invalidate();
        for (var e : b.roles().entrySet()) level.setBlockAndUpdate(e.getKey(), e.getValue() == com.claudemod.entity.life.MineBlueprint.Role.WALK ? Blocks.AIR.defaultBlockState() : Blocks.STONE.defaultBlockState());
        for (int k : new int[] {2, 4}) level.setBlockAndUpdate(b.rows().get(k).feet()[1], Blocks.TORCH.defaultBlockState());
        return b;
    }

