                                BlockPos pk = h.absolutePos(OE_POCKET);
                                check(left.at.equals(pk), "left: on his book at " + left.at.toShortString() + ", the pocket is " + pk.toShortString());
                                int dia = c.inventory.count(s -> s.is(Items.DIAMOND));
