                            check(c.skillQueue.stream().noneMatch(s -> about.contains(s.skill())) && !(c.lastStep != null && about.contains(c.lastStep.skill())), "after stop: a step about them: " + c.skillQueue + ", last " + c.lastSkillLine);
                            check(!com.claudemod.entity.life.Perception.turningRound(c), "after stop: looking all round for them");
                            var sp = com.claudemod.entity.life.Whereabouts.of(c, mock[0]);
