                            c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS, new ItemStack(iron ? Items.IRON_LEGGINGS : Items.LEATHER_LEGGINGS)); c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET, new ItemStack(iron ? Items.IRON_BOOTS : Items.LEATHER_BOOTS));
                            c.getInventory().add(new ItemStack(iron ? Items.IRON_SWORD : Items.STONE_SWORD)); c.getInventory().add(new ItemStack(Items.COOKED_BEEF, 8)); c.getInventory().add(new ItemStack(Items.TORCH, 32));
                            BlockPos you = h.absolutePos(new BlockPos(15, 2, 8)); mock[0].teleportTo(you.getX() + 0.5, you.getY(), you.getZ() + 0.5);
