                            com.claudemod.entity.life.Perception.lookNow(c); com.claudemod.entity.life.Perception.scanStructures(c, level);
                            if (com.claudemod.entity.life.Whereabouts.spot(c, mock[0]) == null) com.claudemod.entity.life.Whereabouts.told(c, mock[0], you);
                            boolean seen = !com.claudemod.entity.life.Perception.sightings(c).isEmpty();
                            check(seen == (sg != 213), "gear gate: the mineshaft " + (seen ? "seen through a stone wall" : "in plain view not seen"));
                            String sit = com.claudemod.director.Structures.describe(c, level); BlockPos np = com.claudemod.director.Structures.nearestPiece(c, level, c.blockPosition(), "mineshaft", 96);
                            check(sit.contains("mineshaft") == seen && (np != null) == seen, "gear gate: what the planner hears (" + sit.trim() + ") or the loot walk's piece (" + np + ") doesn't match what he's seen (" + seen + ")");
                            check(com.claudemod.director.Kit.shortOf(c, com.claudemod.director.Kit.bar("mineshaft")).isEmpty() == iron, "gear gate: the mineshaft bar reads " + com.claudemod.director.Kit.shortOf(c, com.claudemod.director.Kit.bar("mineshaft")) + " in " + (iron ? "iron" : "leather"));
