                        if (t[0] == 50) { var a3 = steps1("obtain", "cooked_beef", 4, "near_you"); a3.addAll(steps1("give", "cooked_beef", 4, "near_them")); com.claudemod.director.ClaudeLife.command(c, mock[0], a3, "get more food for us", "add_after"); } // "and some more food than that if possible"
                        if (t[0] == 70) check(com.claudemod.director.ClaudeLife.giveIfAsked(c, mock[0], "can i have some torches"), "errand: \"can i have some torches\" made no ask"); // the chat-line path
