            oaShell = new java.util.ArrayList<>(); for (var e : b.roles().entrySet()) if (e.getValue() != com.claudemod.entity.life.MineBlueprint.Role.WALK && level.getBlockState(e.getKey()).isSolid()) oaShell.add(e.getKey().immutable());
            com.claudemod.director.ClaudeLife.lavaSeen(c).add(plug.immutable());
