    /** A sealed deepslate block, his small room beside a pool (feet at yy 5, the pool's top at yy 4), the pool's cells seen, a diamond pick and a water bucket, the dragon goal; no mine of his (a ravine's ledge). */
    private static void oaPoolRoom(ClaudeEntity c, GameTestHelper h, ServerLevel level, ServerPlayer[] mock, int[][] lava) {
        for (int x = -4; x <= 30; x++) for (int z = -6; z <= 22; z++) { for (int yy = -3; yy <= 12; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.DEEPSLATE.defaultBlockState(), 2); level.setBlock(h.absolutePos(new BlockPos(x, 13, z)), Blocks.GRASS_BLOCK.defaultBlockState(), 2); }
        for (int[] q : lava) { BlockPos p = h.absolutePos(new BlockPos(q[0], q[1], q[2])); level.setBlock(p, Blocks.LAVA.defaultBlockState(), 2); }
        for (int z = 9; z <= 11; z++) for (int yy = 5; yy <= 6; yy++) level.setBlock(h.absolutePos(new BlockPos(9, yy, z)), Blocks.AIR.defaultBlockState(), 2); // his room: a 2-high nook beside the pool, one above its top
        for (int[] q : lava) com.claudemod.entity.life.Perception.sawCell(c, level, h.absolutePos(new BlockPos(q[0], q[1], q[2]))); // (he saw the pool)
        c.playerGoal = "beat the ender dragon"; com.claudemod.director.ClaudeLife.hisPortal.remove(c.getUUID()); c.prefs.put("mine_model", "legacy");
        c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.DIAMOND_PICKAXE)); c.getInventory().add(new ItemStack(Items.WATER_BUCKET)); c.getInventory().add(new ItemStack(Items.FLINT_AND_STEEL)); c.getInventory().add(new ItemStack(Items.COBBLED_DEEPSLATE, 32)); c.getInventory().add(new ItemStack(Items.TORCH, 16)); c.getInventory().add(new ItemStack(Items.BREAD, 8));
        c.setHealth(20); c.getFoodData().setFoodLevel(20); level.setDayTime(1000); level.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DAYLIGHT).set(false, level.getServer());
        oaStart = h.absolutePos(new BlockPos(9, 5, 9)); c.teleportTo(oaStart.getX() + 0.5, oaStart.getY(), oaStart.getZ() + 0.5);
        BlockPos mk = h.absolutePos(new BlockPos(9, 5, 11)); mock[0].teleportTo(mk.getX() + 0.5, mk.getY(), mk.getZ() + 0.5);
        c.tasks.clear(); c.attempts.clear(); c.dropCurrent = true;
    }
    /** 269 (live 13:35, the ravine pool): a one-deep pool, two cells apart, him one above its top diagonal to the near one, rock over it (no head room): the obsidian made, mined in place, picked up, the other cell next; never off, never "no way to it". */
