                            lnUp = com.claudemod.director.ClaudeLife.nookFrame(b, 1, G); lnPlace(level, c, lnUp);
                            lnLow = com.claudemod.director.ClaudeLife.nookFrame(b, 5, G); lnPlace(level, c, lnLow);
