    private static int drAt; // stages 276-278: when he knew it
    /** A stone block (x -2..12, z -2..12, y 0..9) with a room in it (x 2..8, z 1..8, y 2..4: ceiling y 5); him at (5, 2, me), the mock beside him. */
    private static void drRoom(GameTestHelper h, ServerLevel level, ClaudeEntity c, ServerPlayer[] mock, int me) {
        for (int x = -2; x <= 12; x++) for (int z = -2; z <= 12; z++) for (int yy = 0; yy <= 9; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.STONE.defaultBlockState(), 2);
        for (int x = 2; x <= 8; x++) for (int z = 1; z <= 8; z++) for (int yy = 2; yy <= 4; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.AIR.defaultBlockState(), 2);
        BlockPos p = h.absolutePos(new BlockPos(5, 2, me)); c.teleportTo(p.getX() + 0.5, p.getY(), p.getZ() + 0.5); c.tasks.clear(); c.dropCurrent = true; c.getNavigation().stop();
        if (mock[0] != null) { BlockPos you = h.absolutePos(new BlockPos(3, 2, me)); mock[0].teleportTo(you.getX() + 0.5, you.getY(), you.getZ() + 0.5); }
        c.setHealth(20); c.getFoodData().setFoodLevel(20); level.setDayTime(6000); c.getInventory().clearContent(); c.getInventory().add(new ItemStack(Items.IRON_PICKAXE)); c.getInventory().add(new ItemStack(Items.COBBLESTONE, 32));
    }
    /** Stages 276-278: drips seen through a ceiling (Perception.drips). */
    private static boolean dripStages(int[] stage, int[] t, ClaudeEntity c, GameTestHelper h, ServerLevel level, ServerPlayer[] mock) {
        switch (stage[0]) {
                    case 276, 278 -> { // lava (276) / water (278) sealed over a stone ceiling he looks up at, air under it: seen by drip
                        boolean lv = stage[0] == 276;
                        if (t[0] == 1) { scenarioReset(c); c.blueprint = null; c.skillQueue.clear(); com.claudemod.director.ClaudeLife.lavaSeen(c).clear(); com.claudemod.entity.life.Perception.reset(c); drAt = -1; }
                        if (t[0] > 8 && t[0] % 10 == 0) level.getChunkSource().addRegionTicket(net.minecraft.server.level.TicketType.PORTAL, c.chunkPosition(), 3, c.blockPosition());
                        BlockPos fl = h.absolutePos(new BlockPos(5, 6, 6)), ceil = fl.below();
                        if (t[0] == 10) { drRoom(h, level, c, mock, 3); level.setBlock(fl, (lv ? Blocks.LAVA : Blocks.WATER).defaultBlockState(), 2); }
                        if (t[0] > 10 && drAt < 0) {
                            c.tasks.clear(); c.getLookControl().faceNow(new net.minecraft.world.phys.Vec3(ceil.getX() + 0.5, ceil.getY() - 0.05, ceil.getZ() + 0.5)); // up at the ceiling's underside
                            check(t[0] < 900, "drips: " + (lv ? "lava" : "water") + " over the ceiling he looked up at for 44 s, never seen by its drip");
                            if (com.claudemod.entity.life.Perception.sawDrip(c, fl)) {
                                drAt = t[0];
                                check(lv ? com.claudemod.entity.life.Perception.knowsLava(c, fl) : com.claudemod.entity.life.Perception.knowsWater(c, fl), "drips: seen by its drip, but not on his fluid record");
                                check(com.claudemod.entity.life.Perception.knowsLavaBody(c, level, fl) == lv, "drips: knowsLavaBody reads " + !lv);
                                check(com.claudemod.director.ClaudeLife.lavaSeen(c).contains(fl) == lv && com.claudemod.director.ClaudeLife.byDrip(c, fl) == lv, "drips: his lava list " + com.claudemod.director.ClaudeLife.lavaSeen(c) + ", by drip " + com.claudemod.director.ClaudeLife.byDrip(c, fl));
                                if (lv) {
                                    check(com.claudemod.director.ClaudeLife.dripUnverified(c, fl), "drips: the drip's lava isn't marked unverified");
                                    java.util.List<Task> way = null; for (int k = 0; k < 5 && (way == null || way.isEmpty()); k++) { way = com.claudemod.director.ClaudeLife.dripLavaWay(c, level, fl); if (way == null) break; } // (one spot a call)
                                    check(way != null, "drips: the cast's way to the lava he saw drip plans nothing");
                                    java.util.List<BlockPos> bad = new java.util.ArrayList<>();
                                    for (Task tk : way) if (tk instanceof Task.Break b) for (var d0 : net.minecraft.core.Direction.values()) if (level.getFluidState(b.pos().relative(d0)).is(net.minecraft.tags.FluidTags.LAVA)) bad.add(b.pos());
                                    check(bad.isEmpty(), "drips: the cast's way digs beside the lava he saw drip at " + bad);
                                    c.tasks.clear(); c.tasks.add(new Task.Break(ceil)); // a queued dig of the ceiling cell: held
                                }
                            }
                        }
                        if (lv && drAt > 0 && t[0] == drAt + 80) {
                            check(level.getBlockState(ceil).is(Blocks.STONE) && c.getHealth() >= 20 && !c.isOnFire(), "drips: the ceiling under the lava he saw drip was dug (" + level.getBlockState(ceil) + ", health " + c.getHealth() + ", fire " + c.isOnFire() + ")");
                            level.setBlock(fl, Blocks.AIR.defaultBlockState(), 2); for (int dz = -2; dz <= 0; dz++) level.setBlock(ceil.offset(0, 0, dz), Blocks.AIR.defaultBlockState(), 2); // the lava gone and the ceiling open toward him: he sees no lava there
                        }
                        if (lv && drAt > 0 && t[0] > drAt + 80 && t[0] < drAt + 130) { c.tasks.clear(); c.getLookControl().faceNow(net.minecraft.world.phys.Vec3.atCenterOf(fl)); }
                        if (drAt > 0 && t[0] == drAt + (lv ? 130 : 80)) {
                            if (lv) check(!com.claudemod.director.ClaudeLife.lavaSeen(c).contains(fl), "drips: saw no lava where the drip was, still on his list " + com.claudemod.director.ClaudeLife.lavaSeen(c));
                            pass(stage, t, (lv ? "lava" : "water") + " over the ceiling seen by its drip in " + (drAt - 10) / 20 + " s: on his fluid record" + (lv ? ", his lava list (by drip), the ceiling held, the cast's way round it, off the list once he saw none there" : ""));
                        }
                    }
                    case 277 -> { // the same out of his view: lava over the ceiling behind him, and over the ceiling past a wall in front: neither known
                        if (t[0] == 1) { scenarioReset(c); c.blueprint = null; c.skillQueue.clear(); com.claudemod.director.ClaudeLife.lavaSeen(c).clear(); com.claudemod.entity.life.Perception.reset(c); }
                        if (t[0] > 8 && t[0] % 10 == 0) level.getChunkSource().addRegionTicket(net.minecraft.server.level.TicketType.PORTAL, c.chunkPosition(), 3, c.blockPosition());
                        BlockPos back = h.absolutePos(new BlockPos(5, 6, 7)), front = h.absolutePos(new BlockPos(5, 6, 1));
                        if (t[0] == 10) {
                            drRoom(h, level, c, mock, 4); level.setBlock(back, Blocks.LAVA.defaultBlockState(), 2); level.setBlock(front, Blocks.LAVA.defaultBlockState(), 2);
                            for (int x = 2; x <= 8; x++) for (int yy = 2; yy <= 4; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, 3)), Blocks.STONE.defaultBlockState(), 2); // the wall between him and the front ceiling
                        }
                        if (t[0] > 10 && t[0] < 500) { c.tasks.clear(); BlockPos at = h.absolutePos(new BlockPos(5, 3, 1)); c.getLookControl().faceNow(new net.minecraft.world.phys.Vec3(at.getX() + 0.5, front.getY() - 1.05, at.getZ() + 0.5)); } // facing north, up at the wall's top (the front drip's line)
                        if (t[0] == 500) {
                            for (BlockPos q : new BlockPos[] {back, front}) check(!com.claudemod.entity.life.Perception.sawDrip(c, q) && !com.claudemod.entity.life.Perception.knowsLava(c, q) && !com.claudemod.director.ClaudeLife.lavaSeen(c).contains(q), "drips: knew the lava over the ceiling at " + q.toShortString() + " he couldn't see the underside of (" + (q.equals(back) ? "behind him" : "past the wall") + ")");
                            check(com.claudemod.director.ClaudeLife.lavaSeen(c).isEmpty(), "drips: his lava list " + com.claudemod.director.ClaudeLife.lavaSeen(c));
                            pass(stage, t, "lava over a ceiling behind him and over one past a wall: 24 s, neither known");
                        }
                    }
                    default -> { return exactStages(stage, t, c, h, level, mock); }
        }
        return true;
    }

    // ---- stages 440-442: self-defence on their go_to order (live 17:09: nine zombie hits unanswered while he chased a phantom) ----
    private static net.minecraft.world.entity.monster.Zombie sdZ; private static net.minecraft.world.entity.monster.Phantom sdP; private static int sdHit = -1, sdFight = -1, sdDead = -1;
    private static void sdStage(int[] stage, int[] t, ClaudeEntity c, GameTestHelper h, ServerLevel level, ServerPlayer[] mock) {
        boolean withPhantom = stage[0] == 441; net.minecraft.world.item.Item axe = stage[0] == 442 ? Items.NETHERITE_AXE : Items.DIAMOND_AXE;
        if (t[0] == 1) {
            scenarioReset(c); com.claudemod.entity.life.Perception.reset(c);
            for (var m : level.getEntitiesOfClass(net.minecraft.world.entity.Mob.class, c.getBoundingBox().inflate(64))) m.discard();
            c.commandActive = false; c.commandResults.clear(); c.lastSkillLine = ""; c.lastStep = null; c.nextPlanTick = c.tickCount + 20 * 600; c.prefs.put("stay_close", "no");
            sdZ = null; sdP = null; sdHit = -1; sdFight = -1; sdDead = -1;
        }
        if (t[0] == 10) {
            flatBox(h); level.setDayTime(6000);
            BlockPos me = h.absolutePos(new BlockPos(3, 2, 3)), you = h.absolutePos(new BlockPos(14, 2, 14));
            c.teleportTo(me.getX() + 0.5, me.getY(), me.getZ() + 0.5); mock[0].teleportTo(you.getX() + 0.5, you.getY(), you.getZ() + 0.5);
            c.getInventory().clearContent(); c.getInventory().add(new ItemStack(axe)); c.getInventory().add(new ItemStack(Items.DIAMOND_PICKAXE)); c.getInventory().add(new ItemStack(Items.COOKED_BEEF, 62)); c.getInventory().add(new ItemStack(Items.DIRT, 8));
            c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, new ItemStack(Items.DIAMOND_HELMET)); c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.CHEST, new ItemStack(Items.DIAMOND_CHESTPLATE));
            c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.LEGS, new ItemStack(Items.DIAMOND_LEGGINGS)); c.setItemSlot(net.minecraft.world.entity.EquipmentSlot.FEET, new ItemStack(Items.DIAMOND_BOOTS));
            c.setHealth(20); c.getFoodData().setFoodLevel(20);
            com.claudemod.director.ClaudeLife.command(c, mock[0], steps1("go_to", "", 1, "near_them"), "come here", "replace");
        }
        if (withPhantom && t[0] == 14) { // a phantom 6 up and 3 off, out of his reach, hits him: he goes for it (as live, 17:09:23)
            sdP = EntityType.PHANTOM.create(level); sdP.moveTo(c.getX() + 3, c.getY() + 6, c.getZ(), 0, 0); sdP.setNoAi(true); sdP.setPersistenceRequired();
            sdP.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.FIRE_RESISTANCE, 20 * 120)); level.addFreshEntity(sdP);
            sdP.doHurtTarget(c);
        }
        if (t[0] == (withPhantom ? 24 : 14)) {
            if (withPhantom) check(c.currentTask instanceof Task.Attack a0 && a0.target().equals(sdP.getUUID()), "441 setup: not going for the phantom after its hit, doing " + c.currentTask + " tasks=" + c.tasks);
            sdZ = EntityType.ZOMBIE.create(level); sdZ.moveTo(c.getX() - 1.2, c.getY(), c.getZ() - 1.2, 0, 0); sdZ.setPersistenceRequired();
            sdZ.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD, new ItemStack(Items.IRON_HELMET)); level.addFreshEntity(sdZ); sdZ.setTarget(c);
        }
        if (sdZ != null && sdHit < 0) { // a real zombie hit (ClaudeEntity.hurt, Perception.felt); again each tick while his hurt-time from the last hit holds it off
            float hp0 = c.getHealth(); c.urgentAttacker = null; boolean hit = sdZ.doHurtTarget(c);
            if (hit) { sdHit = t[0]; ClaudeMod.LOGGER.info("[Claude test] stage {} zombie hit him: health {} -> {}, attacker {}, doing {}", stage[0], hp0, c.getHealth(), c.urgentAttacker, c.currentTask); }
            else check(t[0] < (withPhantom ? 24 : 14) + 40, stage[0] + " setup: the zombie's hit never landed in 2 s");
        }
        if (sdHit > 0 && t[0] > sdHit) {
            if (sdFight < 0 && c.currentTask instanceof Task.Attack a && a.target().equals(sdZ.getUUID())) sdFight = t[0];
            check(sdFight > 0 || t[0] - sdHit <= 20, stage[0] + ": 1 s after the zombie's hit, not fighting it: doing " + c.currentTask + " attacker=" + c.urgentAttacker + " tasks=" + c.tasks);
            check(!(c.currentTask instanceof Task.Flee), stage[0] + ": ran from one zombie in diamond armor with a " + axe + " (health " + c.getHealth() + ")");
            if (sdDead < 0 && !sdZ.isAlive()) sdDead = t[0];
            if (sdDead < 0) check(t[0] - sdHit < 300, stage[0] + ": the zombie still up 15 s after its hit (" + sdZ.getHealth() + " hp), his health " + c.getHealth() + ", doing " + c.currentTask);
            else if (withPhantom) { sdP.discard(); pass(stage, t, "on the phantom out of reach, the zombie's hit turned him on it in " + (sdFight - sdHit) + " ticks; dead in " + (sdDead - sdHit) + " ticks, health " + (int) c.getHealth()); }
            else if (c.distanceTo(mock[0]) <= 5) pass(stage, t, "on their go_to with a " + axe + ": fighting the zombie " + (sdFight - sdHit) + " ticks after its hit, dead in " + (sdDead - sdHit) + ", health " + (int) c.getHealth() + ", then on to them (" + (t[0] - sdDead) + " ticks)");
            else check(t[0] - sdDead < 300, stage[0] + ": the zombie dead 15 s ago and not back to them: " + (int) c.distanceTo(mock[0]) + " off, doing " + c.currentTask + " tasks=" + c.tasks + " last=" + c.lastSkillLine);
        }
    }

    // ---------------------------------------------------------------- drops and jumps (stages 380-389)
    private static int djMark = -1, djPh = 0; private static float djHp, djMin = 20; private static String djLine = ""; private static final java.util.Set<Integer> djKinds = new java.util.HashSet<>();
    /** Each tick of a drop/jump stage: the lowest health seen (natural regen heals a fall's HP back within seconds), and the kinds of leap he ran. */
    private static void djWatch(ClaudeEntity c) { djMin = Math.min(djMin, c.getHealth()); if (c.currentTask instanceof Task.Leap l) djKinds.add(l.kind()); }
    private static void djReset(ClaudeEntity c) {
        scenarioReset(c); com.claudemod.entity.nav.Leaps.reset(c); com.claudemod.entity.life.Perception.reset(c); com.claudemod.director.Primitives.reset(c);
        c.planning = false; c.failCount.clear(); c.commandResults.clear(); c.commandActive = false; c.lastSkillLine = ""; c.lastStep = null; c.prefs.put("stay_close", "no"); c.nextPlanTick = c.tickCount + 20 * 600; c.lessonOpen = ""; c.staying = false; c.setShiftKeyDown(false);
        djMark = -1; djPh = 0; djHp = 0; djMin = 20; djLine = ""; djKinds.clear();
    }
    /** Stone to y 1 over the 16x16, air above to height + 8; a plateau x 0-6 standing height blocks over the floor (its top cell y height + 1, his feet height + 2). */
    private static void djCliff(GameTestHelper h, ServerLevel level, int height) {
        for (int x = 0; x < 16; x++) for (int z = 0; z < 16; z++) { for (int yy = -3; yy <= 1; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), Blocks.STONE.defaultBlockState(), 2); for (int yy = 2; yy <= height + 8; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), (x <= 6 && yy <= height + 1 ? Blocks.STONE : Blocks.AIR).defaultBlockState(), 2); }
        level.setDayTime(6000);
    }
    private static void djPut(ClaudeEntity c, GameTestHelper h, BlockPos rel) { BlockPos p = h.absolutePos(rel); c.teleportTo(p.getX() + 0.5, p.getY(), p.getZ() + 0.5); c.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO); c.fallDistance = 0; wbFace(c, -90f); c.setHealth(20); c.getFoodData().setFoodLevel(20); }
    private static void djMock(ServerPlayer[] mock, GameTestHelper h, BlockPos rel) { if (mock[0] == null) return; BlockPos p = h.absolutePos(rel); mock[0].teleportTo(p.getX() + 0.5, p.getY(), p.getZ() + 0.5); }

    /** A trench across the box (x from..to, z 1-14), floor y 1 elsewhere; bedrock walls along z 0 and 15 (no way round the ends); its bottom 'deep' under the floor top, lava in it with lava = true. */
    private static void djTrench(GameTestHelper h, ServerLevel level, int from, int to, int deep, boolean lava) {
        djCliff(h, level, 0);
        for (int x = 0; x < 16; x++) for (int yy = -3; yy <= 5; yy++) { level.setBlock(h.absolutePos(new BlockPos(x, yy, 0)), Blocks.BEDROCK.defaultBlockState(), 2); level.setBlock(h.absolutePos(new BlockPos(x, yy, 15)), Blocks.BEDROCK.defaultBlockState(), 2); }
        for (int x = from; x <= to; x++) for (int z = 1; z <= 14; z++) for (int yy = 2 - deep; yy <= 1; yy++) level.setBlock(h.absolutePos(new BlockPos(x, yy, z)), (lava && yy == 2 - deep ? Blocks.LAVA : Blocks.AIR).defaultBlockState(), 2);
    }
    /** One jump stage: him at (3, 2, 8) facing east, a walk to (13, y, 8); passes once there with the kind of jump wanted run, never down in the trench, no HP lost, in a player's time. */
    private static void djJumpStage(int[] stage, int[] t, ClaudeEntity c, GameTestHelper h, ServerLevel level, int wantKind, int toY, int maxTicks, String what) {
        BlockPos to = h.absolutePos(new BlockPos(13, toY, 8));
        if (t[0] > 10) {
            djWatch(c);
            check(c.getY() > h.absolutePos(new BlockPos(0, 2, 0)).getY() - 0.5, what + ": down in the gap at " + c.blockPosition().toShortString() + " (kinds run " + djKinds + ")");
            if (c.blockPosition().distSqr(to) <= 1 && c.onGround() && c.tasks.isEmpty() && c.currentTask == null) {
                check(djKinds.contains(wantKind), what + ": no " + com.claudemod.entity.nav.Leaps.kindName(wantKind) + " run (kinds " + djKinds + ")");
                check(djMin > 19.99f, what + ": hurt (lowest health " + djMin + ")");
                check(t[0] - djMark <= maxTicks, what + ": " + (t[0] - djMark) + " ticks (a player: under " + maxTicks + ")");
                int put = 0; for (BlockPos p : BlockPos.betweenClosed(h.absolutePos(new BlockPos(0, -3, 1)), h.absolutePos(new BlockPos(15, 6, 14)))) if (level.getBlockState(p).is(Blocks.COBBLESTONE) || level.getBlockState(p).is(Blocks.DIRT)) put++;
                check(put == 0, what + ": " + put + " block(s) put down");
                pass(stage, t, what + " in " + (t[0] - djMark) + " ticks (kinds " + djKinds + ")");
            } else if (c.tasks.isEmpty() && c.currentTask == null && t[0] % 40 == 0 && t[0] - djMark > 40) c.tasks.add(new Task.GoTo(to, 0.5));
            else check(t[0] - djMark < 600, what + ": not across in 30 s: at " + c.blockPosition().toShortString() + " y=" + String.format("%.2f", c.getY()) + " now " + c.currentTask + " tasks " + c.tasks + " kinds " + djKinds);
        }
    }

    private static void pass(int[] stage, int[] t, String what) {
        ClaudeMod.LOGGER.info("[Claude test] PASS stage {}: {}", stage[0], what);
        stage[0]++;
        if (stage[0] == Integer.getInteger("claude.endStage", -1) + 1) stage[0] = 9999; // -Dclaude.endStage=N: the run ends after stage N
        t[0] = 0;
    }

