                            com.claudemod.director.Primitives.move(c, mock[0], new com.claudemod.entity.life.Skills.Step("move", "face east", 1, "")); // facing east to start
                            com.claudemod.director.ClaudeLife.command(c, mock[0], prSteps("move", "turn around", "move", "forward 2", "move", "face north", "move", "forward 1", "move", "crouch"), "turn round, two steps forward, face north, one more, crouch");
