                            for (int x = 4; x <= 14; x++) for (int z = 7; z <= 9; z++) for (int yy = 2; yy <= 5; yy++) h.setBlock(new BlockPos(x, yy, z), Blocks.AIR); // the corridor, 3 wide 4 high
                            for (int x = 1; x <= 3; x++) for (int yy = 2; yy <= 3; yy++) h.setBlock(new BlockPos(x, yy, 8), Blocks.AIR); // the 2-high gap off its end
