                            String[][] cases = {{"what do you need for the nether", "flint and steel first, then a shield, more blocks, and gold for piglin boots"},
                                {"skip the flint and steel for now", "got it, skipping flint and steel. shield and gold boots next"},
                                {"what's next", "ok, shield's next on my list"},
                                {"do you have any gold?", "i've got raw gold in my chest"},
                                {"ready for the nether?", "still need a shield and gold boots for the nether"}};
                            for (String[] k : cases) { String said = com.claudemod.director.ClaudeChat.replyTruth(c, mock[0], k[1], rtReply(k[1]), k[0]); check(k[1].equals(said), "gear truth: a need/list line rewritten (asked \"" + k[0] + "\"): \"" + k[1] + "\" said as \"" + said + "\""); }
                            rtGear(c);
